const upsertPlacement = `-- name: UpsertPlacement :one
INSERT INTO placements (resource_id, cluster_id, region, deployment_id, desired_spec, environment_id, secret_env)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (resource_id, environment_id, cluster_id) DO UPDATE
SET region = EXCLUDED.region,
    deployment_id = EXCLUDED.deployment_id,
    desired_spec = EXCLUDED.desired_spec,
    secret_env = EXCLUDED.secret_env,
    desired_deleted = false,
    desired_revision = placements.desired_revision + 1,
    applied_error = NULL,
    retry_after = NULL,
    apply_attempts = 0,
    apply_failed = false,
    updated_at = NOW()
RETURNING id, desired_revision
`

type UpsertPlacementParams struct {
	ResourceID    uuid.UUID         `json:"resourceId"`
	ClusterID     uuid.UUID         `json:"clusterId"`
	Region        string            `json:"region"`
	DeploymentID  *uuid.UUID        `json:"deploymentId"`
	DesiredSpec   []byte            `json:"desiredSpec"`
	EnvironmentID uuid.UUID         `json:"environmentId"`
	SecretEnv     map[string]string `json:"secretEnv"`
}

type UpsertPlacementRow struct {
	ID              uuid.UUID `json:"id"`
	DesiredRevision int64     `json:"desiredRevision"`
}

func (q *Queries) UpsertPlacement(ctx context.Context, arg UpsertPlacementParams) (UpsertPlacementRow, error) {
	row := q.db.QueryRow(ctx, upsertPlacement,
		arg.ResourceID,
		arg.ClusterID,
		arg.Region,
		arg.DeploymentID,
		arg.DesiredSpec,
		arg.EnvironmentID,
		arg.SecretEnv,
	)
	var i UpsertPlacementRow
	err := row.Scan(&i.ID, &i.DesiredRevision)
	return i, err
}

const workspaceHasPlacementWindowSince = `-- name: WorkspaceHasPlacementWindowSince :one
SELECT EXISTS (
    SELECT 1 FROM placement_windows
    WHERE workspace_id = $1
      AND cluster_id = $2
      AND (removed_at IS NULL OR removed_at > $3::timestamptz)
)
`

type WorkspaceHasPlacementWindowSinceParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	ClusterID   uuid.UUID `json:"clusterId"`
	Since       time.Time `json:"since"`
}

// Reports whether the workspace has a placement on the cluster that is open or was removed after since.
func (q *Queries) WorkspaceHasPlacementWindowSince(ctx context.Context, arg WorkspaceHasPlacementWindowSinceParams) (bool, error) {
	row := q.db.QueryRow(ctx, workspaceHasPlacementWindowSince, arg.WorkspaceID, arg.ClusterID, arg.Since)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
